function renderPartners(){const e=document.getElementById("parceiros-recomendados"),r=document.getElementById("parceiros-grid");if(!e||!r)return;const t=(window.partners||[]).filter(e=>e.active).sort((e,r)=>e.order-r.order);if(!t.length)return e.hidden=!0,void(r.innerHTML="");r.innerHTML=t.map(e=>{const r=e.ctaText?`
      <a class="parceiro-cta" href="${e.url}" target="_blank" rel="noopener noreferrer">
        <span>${e.ctaText}</span>
        <span aria-hidden="true">-&gt;</span>
      </a>
    `:"";return`
      <div class="parceiro-item">
        <a class="parceiro-banner" href="${e.url}" target="_blank" rel="noopener noreferrer" aria-label="${e.name}">
          <img src="${e.image}" alt="${e.alt}" loading="lazy">
        </a>
        ${r}
      </div>
    `}).join(""),r.classList.toggle("parceiros-grid--single",1===t.length),e.hidden=!1}document.addEventListener("DOMContentLoaded",renderPartners);
